"""
MeshForge 3D — Offline License Manager (Pro/Studio tiers)
==========================================================
Lightweight, dependency-free licensing for indie sales:

  * Keys are generated by the seller with:  python -m core.license_manager gen pro 2027-06
  * Key format:  MESHF-XXXXX-XXXXX-XXXXX-XXXXX   (payload + HMAC-SHA256 signature)
  * Validation is fully OFFLINE - no phone-home, fits the product's privacy USP.
  * Tiers: free | pro | studio
  * Optional machine binding: pass --bind to lock key to one machine ID.

Integration:
    from core.license_manager import validate_license, current_machine_id
"""

import base64
import hashlib
import hmac
import json
import os
import struct
import subprocess
import time

# Obfuscated shared secret (indie-grade; move to server-side for stronger DRM)
_SECRET = bytes([0x4D, 0x65, 0x73, 0x68, 0x46, 0x6F, 0x72, 0x67,
                 0x65, 0x33, 0x44, 0x21, 0x40, 0x23, 0x24, 0x25])
_KEY_PREFIX = "MESHF"
_CHUNK = 5

LICENSE_FILE = os.path.join(os.path.expanduser("~"), ".meshforge3d_license")


# ---------------------------------------------------------------------------
# Machine ID (optional binding)
# ---------------------------------------------------------------------------
def current_machine_id() -> str:
    """Stable per-machine identifier (Windows: machine GUID; fallback: hostname)."""
    try:
        out = subprocess.run(
            ["reg", "query", r"HKLM\SOFTWARE\Microsoft\Cryptography", "/v", "MachineGuid"],
            capture_output=True, text=True, timeout=5,
        ).stdout
        for line in out.splitlines():
            if "MachineGuid" in line:
                return line.split()[-1].strip()
    except Exception:
        pass
    return hashlib.sha256(os.environ.get("COMPUTERNAME", "unknown").encode()).hexdigest()[:16]


# ---------------------------------------------------------------------------
# Key codec
# ---------------------------------------------------------------------------
def _b32_encode(data: bytes) -> str:
    return base64.b32encode(data).decode().rstrip("=")


def _b32_decode(text: str) -> bytes:
    pad = "=" * ((8 - len(text) % 8) % 8)
    return base64.b32decode(text + pad)


def _sign(payload: bytes) -> bytes:
    return hmac.new(_SECRET, payload, hashlib.sha256).digest()[:10]


def generate_key(tier: str = "pro", expires_yyyymm: int = 0, bind_machine: bool = False) -> str:
    """Seller-side key generation."""
    tier_code = {"free": 0, "pro": 1, "studio": 2}.get(tier, 1)
    flags = 1 if bind_machine else 0
    payload = struct.pack(">BBI", tier_code, flags, expires_yyyymm)
    raw = payload + _sign(payload)
    body = _b32_encode(raw)
    chunks = [body[i:i + _CHUNK] for i in range(0, len(body), _CHUNK)]
    return "-".join([_KEY_PREFIX] + chunks)


def parse_key(key: str):
    """Returns dict(tier, expires_yyyymm, bind_machine) or None if invalid."""
    try:
        clean = key.strip().upper().replace(" ", "")
        parts = clean.split("-")
        if len(parts) < 2 or parts[0] != _KEY_PREFIX:
            return None
        raw = _b32_decode("".join(parts[1:]))
        payload, sig = raw[:-10], raw[-10:]
        if not hmac.compare_digest(_sign(payload), sig):
            return None
        tier_code, flags, expires = struct.unpack(">BBI", payload)
        tier = {0: "free", 1: "pro", 2: "studio"}.get(tier_code, "free")
        return {"tier": tier, "expires_yyyymm": expires, "bind_machine": bool(flags)}
    except Exception:
        return None


# ---------------------------------------------------------------------------
# Persistence & validation
# ---------------------------------------------------------------------------
def save_license(key: str) -> bool:
    info = parse_key(key)
    if info is None:
        return False
    with open(LICENSE_FILE, "w", encoding="utf-8") as f:
        json.dump({"key": key.strip(), "machine": current_machine_id()}, f)
    return True


def load_saved_key() -> str:
    try:
        with open(LICENSE_FILE, "r", encoding="utf-8") as f:
            return json.load(f).get("key", "")
    except Exception:
        return ""


def validate_license(key: str = "") -> dict:
    """Full validation: signature, expiry, optional machine binding."""
    key = key or load_saved_key()
    info = parse_key(key)
    if info is None:
        return {"valid": False, "tier": "free", "reason": "invalid_or_missing"}

    now_yyyymm = time.gmtime().tm_year * 100 + time.gmtime().tm_mon
    exp = info["expires_yyyymm"]
    if exp and now_yyyymm > exp:
        return {"valid": False, "tier": "free", "reason": "expired"}

    if info["bind_machine"]:
        saved = ""
        try:
            with open(LICENSE_FILE, "r", encoding="utf-8") as f:
                saved = json.load(f).get("machine", "")
        except Exception:
            pass
        if saved and saved != current_machine_id():
            return {"valid": False, "tier": "free", "reason": "machine_mismatch"}

    return {"valid": True, "tier": info["tier"], "expires_yyyymm": exp}


# ---------------------------------------------------------------------------
# Seller CLI:  python -m core.license_manager gen pro 202706 [--bind]
# ---------------------------------------------------------------------------
if __name__ == "__main__":
    import argparse
    p = argparse.ArgumentParser(description="MeshForge 3D license key tool")
    sub = p.add_subparsers(dest="cmd", required=True)
    g = sub.add_parser("gen", help="generate a license key")
    g.add_argument("tier", choices=["free", "pro", "studio"])
    g.add_argument("expires", help="YYYYMM or 0 for perpetual")
    g.add_argument("--bind", action="store_true", help="lock to first activated machine")
    sub.add_parser("check", help="validate a key")
    sub.add_parser("check-saved", help="validate the locally saved key")
    sub.add_parser("machine-id", help="print this machine's ID")
    args = p.parse_args()

    if args.cmd == "gen":
        print(generate_key(args.tier, int(args.expires), args.bind))
    elif args.cmd == "check":
        print(json.dumps(validate_license(input("Key: ")), indent=2))
    elif args.cmd == "check-saved":
        print(json.dumps(validate_license(), indent=2))
    else:
        print(current_machine_id())